package cn.mop.api;
import cn.mop.domain.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class SlaComplianceScenarioControllerTest {
    static final String ACTOR="56000000-0000-4000-8000-000000000001",TENANT="56000000-0000-4000-8000-000000000011",TIME="2026-10-01T00:00:00Z";
    ObjectMapper mapper=new ObjectMapper();PlatformRepository platform;SlaComplianceScenarioController controller;
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);controller=new SlaComplianceScenarioController(platform);role("padmin");}
    void role(String role){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,role,7,true)));}
    MockHttpServletRequest request(){var r=new MockHttpServletRequest("POST","/api/v1/sla/compliance-scenarios");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setAttribute("mop.trace_id","synthetic-scenario");return r;}
    ObjectNode row(String id){var r=mapper.createObjectNode().put("scenario_ref",id).put("priority","P1").put("exclusion","NONE").putNull("exclusion_approval");r.putObject("sla_snapshot").put("id","scenario-only").put("version",1);for(String key:List.of("response_due_at","recovery_due_at","response_actual_at","recovery_actual_at"))r.put(key,TIME);return r;}
    ObjectNode input(){var b=mapper.createObjectNode().put("population_complete",true);b.putArray("tickets").add(row("case-1"));return b;}
    ObjectNode first(ObjectNode b){return (ObjectNode)b.get("tickets").get(0);}
    Map<?,?> result(ObjectNode b){return (Map<?,?>)((Map<?,?>)controller.calculate(b,request())).get("data");}
    Map<?,?> item(Map<?,?> r){return (Map<?,?>)((List<?>)r.get("items")).get(0);}
    void invalid(ObjectNode b){assertEquals(400,assertThrows(DomainException.class,()->result(b)).status);}
    @Test void exactTenWithThreeLateProducesSevenTenthsButNoFormalAchievement(){var b=input();var rows=(ArrayNode)b.get("tickets");rows.removeAll();for(int i=0;i<10;i++)rows.add(row("case-"+i).put("response_actual_at",i<3?"2026-10-01T00:00:00.001Z":TIME));var r=result(b);assertEquals(Map.of("numerator",7L,"denominator",10L),r.get("scenario_achievement"));assertEquals(TENANT,r.get("tenant_id"));assertEquals("EXPLICIT_INPUT_NOT_PROJECT_DATA",r.get("source"));assertEquals(false,r.get("effective"));assertNull(r.get("effective_achievement"));assertNull(r.get("compensation_amount"));assertEquals("CONFIG_PENDING",r.get("compensation_status"));verify(platform).membership(ACTOR,TENANT);verifyNoMoreInteractions(platform);}
    @Test void boundaryAndOffsetAreExact(){var b=input();first(b).put("response_actual_at","2026-10-01T08:00:00+08:00");assertEquals("MET",item(result(b)).get("scenario_outcome"));first(b).put("recovery_actual_at","2026-10-01T00:00:00.001Z");assertEquals("NOT_MET",item(result(b)).get("scenario_outcome"));}
    @Test void missingTimingOrSnapshotNeverBecomesMet(){for(String key:List.of("response_due_at","recovery_due_at","response_actual_at","recovery_actual_at","sla_snapshot")){var b=input();first(b).putNull(key);var r=result(b);assertEquals("UNRESOLVED",r.get("status"));assertNull(r.get("scenario_achievement"));assertEquals("UNRESOLVED",item(r).get("scenario_outcome"));}}
    @Test void unknownScopeIsNotSilentlyRemovedFromDenominator(){for(String key:List.of("priority","exclusion")){var b=input();first(b).putNull(key);var r=result(b);assertEquals("APPLICABILITY_UNKNOWN",r.get("reason"));assertNull(item(r).get("applicable"));assertNull(r.get("scenario_achievement"));}}
    @Test void pendingAndRejectedExclusionsStayApplicable(){for(String exclusion:List.of("PENDING_APPROVAL","REJECTED")){var b=input();first(b).put("exclusion",exclusion);var r=result(b);assertEquals(true,item(r).get("applicable"));assertEquals(true,item(r).get("unapproved_exclusion_ignored"));assertEquals(Map.of("numerator",1L,"denominator",1L),r.get("scenario_achievement"));}}
    @Test void declaredApprovalStillDoesNotValidateRealApproval(){var b=input();first(b).put("exclusion","APPROVED");assertEquals("APPLICABILITY_UNKNOWN",result(b).get("reason"));first(b).putObject("exclusion_approval").put("id","hypothetical").put("version",2);var r=result(b);assertEquals("NO_APPLICABLE",r.get("status"));assertEquals(true,item(r).get("exclusion_applied_in_scenario"));assertEquals("UNVERIFIED",r.get("approval_validation_status"));assertEquals("NOT_CHECKED",r.get("runtime_snapshot_validation"));assertNull(r.get("scenario_achievement"));}
    @Test void emptyAndIncompletePopulationsHaveNoRatio(){var b=input();b.putNull("population_complete");assertEquals("POPULATION_NOT_COMPLETE",result(b).get("reason"));b.put("population_complete",false);assertNull(result(b).get("scenario_achievement"));b.put("population_complete",true);((ArrayNode)b.get("tickets")).removeAll();assertEquals("NO_APPLICABLE",result(b).get("status"));}
    @Test void rolesAndCurrentMembershipAreRequired(){role("msp");assertEquals("CALCULATED",result(input()).get("status"));for(String role:List.of("viewer","tadmin","unknown")){role(role);assertEquals(403,assertThrows(DomainException.class,()->result(input())).status);}when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",7,false)));assertEquals(401,assertThrows(DomainException.class,()->result(input())).status);var r=request();r.setUserPrincipal(null);assertEquals(401,assertThrows(DomainException.class,()->controller.calculate(input(),r)).status);}
    @Test void strictShapeAndQueryRejectAuthorityOverrides(){for(String key:List.of("tenant_id","actor_id","effective","compensation_amount"))invalid(input().put(key,"forged"));var b=input();first(b).remove("priority");invalid(b);var r=request();r.addParameter("tenant_id",TENANT);assertEquals(400,assertThrows(DomainException.class,()->controller.calculate(input(),r)).status);b=input();first(b).put("priority","p1");invalid(b);}
    @Test void boundedUniqueReferencesAndTimestampPrecision(){var b=input();((ArrayNode)b.get("tickets")).add(row("case-1"));invalid(b);b=input();var rows=(ArrayNode)b.get("tickets");for(int i=1;i<=200;i++)rows.add(row("case-"+(i+1)));invalid(b);rows.remove(200);assertEquals(200,((List<?>)result(b).get("items")).size());for(String time:List.of("2026-10-01","2026-10-01T00:00:00.0001Z","2026-13-01T00:00:00Z")){b=input();first(b).put("response_actual_at",time);invalid(b);}b=input();first(b).put("scenario_ref","😀".repeat(160));assertEquals("CALCULATED",result(b).get("status"));first(b).put("scenario_ref","😀".repeat(161));invalid(b);}
    @Test void rawBodyRejectsDuplicatesTrailingDeepAndOverBudgetAndAcceptsFullBatch()throws Exception{for(String raw:List.of("{\"tickets\":[],\"tickets\":[]}","{} {}","[[[[[1]]]]]"," ".repeat(262145))){var r=request();r.setContent(raw.getBytes(StandardCharsets.UTF_8));assertEquals(400,assertThrows(DomainException.class,()->SlaComplianceScenarioController.body(r)).status);}var b=input();var rows=(ArrayNode)b.get("tickets");for(int i=1;i<200;i++)rows.add(row("case-"+(i+1)));var r=request();r.setContent(mapper.writeValueAsBytes(b));assertEquals(b,SlaComplianceScenarioController.body(r));}
}
